import re
import sys

assignment = re.compile(
    r"\s*(a|b|c|d|e|f|g|h|i|j|k|l|m|n|o|p|TMP)"
    r"\s*<-\s*(?:(\d+)|\(\s*\1\s*\+\s*(\d+)\s*\)\s*mod\s*100)\s*;"
)

values = {}

for line in sys.stdin:
    match = assignment.fullmatch(line.strip())
    if match is None:
        continue

    name, direct_value, increment = match.groups()
    if direct_value is not None:
        values[name] = int(direct_value)
    else:
        values[name] = (values[name] + int(increment)) % 100

names = list("abcdefghijklmnop") + ["TMP"]
print(" ".join(f"{name} ?= {values[name]};" for name in names))
